BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path TO public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
SELECT ('63000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000',
 'authenticated','authenticated','account-'||i||'@example.invalid','x',now(),now(),now() FROM generate_series(1,5) i;
INSERT INTO public.profiles(id,name) SELECT id,'Synthetic account' FROM auth.users WHERE id::text LIKE '63000000-%' ON CONFLICT(id) DO NOTHING;
INSERT INTO public.organizations(id,name) VALUES('63000000-0000-4000-8000-000000000010','Account fixture'),('63000000-0000-4000-8000-000000000020','Foreign fixture');
INSERT INTO public.organization_members(organization_id,user_id,role)
SELECT '63000000-0000-4000-8000-000000000010',('63000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,
 CASE WHEN i=1 THEN 'owner' ELSE 'member' END FROM generate_series(1,4) i;
INSERT INTO public.organization_members(organization_id,user_id,role) VALUES('63000000-0000-4000-8000-000000000020','63000000-0000-4000-8000-000000000005','owner');
INSERT INTO public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at)
SELECT 'account-hash-'||i,'account-session-'||i,('63000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,now(),now()+interval '1 hour' FROM generate_series(1,5) i;
INSERT INTO public.organization_roles(id,organization_id,name,permissions) VALUES
('63000000-0000-4000-8000-000000000030','63000000-0000-4000-8000-000000000010','Reader','{"records":{"view":"assigned"}}'),
('63000000-0000-4000-8000-000000000031','63000000-0000-4000-8000-000000000010','Equivalent reader','{"records":{"view":"assigned"}}'),
('63000000-0000-4000-8000-000000000032','63000000-0000-4000-8000-000000000010','Manager','{"management":{"accounts":true,"roles":true}}');
INSERT INTO public.organization_member_roles(organization_id,user_id,role_id) VALUES('63000000-0000-4000-8000-000000000010','63000000-0000-4000-8000-000000000003','63000000-0000-4000-8000-000000000030'),('63000000-0000-4000-8000-000000000010','63000000-0000-4000-8000-000000000004','63000000-0000-4000-8000-000000000032');
CREATE FUNCTION pg_temp.flush() RETURNS void LANGUAGE plpgsql AS $$ BEGIN SET CONSTRAINTS ALL IMMEDIATE; SET CONSTRAINTS ALL DEFERRED; END $$;
SELECT pg_temp.flush();
CREATE FUNCTION pg_temp.assign(p_user uuid,p_roles uuid[]) RETURNS void LANGUAGE plpgsql AS $$
BEGIN PERFORM public.account_replace_member_roles('63000000-0000-4000-8000-000000000010',p_user,p_roles); PERFORM pg_temp.flush(); END $$;
CREATE FUNCTION pg_temp.remove(p_user uuid) RETURNS void LANGUAGE plpgsql AS $$
BEGIN PERFORM public.account_remove('63000000-0000-4000-8000-000000000010',p_user,'active'); PERFORM pg_temp.flush(); END $$;
CREATE FUNCTION pg_temp.edit_role(p_permissions jsonb,p_name text DEFAULT 'Reader') RETURNS void LANGUAGE plpgsql AS $$
BEGIN PERFORM public.mutate_organization_role_authorized('63000000-0000-4000-8000-000000000010','63000000-0000-4000-8000-000000000030','update',p_name,NULL,p_permissions,false); PERFORM pg_temp.flush(); END $$;
CREATE FUNCTION pg_temp.add_owner(p_user uuid,p_token text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN PERFORM public.add_organization_owner_atomic('63000000-0000-4000-8000-000000000010',p_user,p_token); PERFORM pg_temp.flush(); END $$;
CREATE FUNCTION pg_temp.transfer(p_user uuid) RETURNS void LANGUAGE plpgsql AS $$
BEGIN PERFORM public.transfer_owner_atomic('63000000-0000-4000-8000-000000000010',p_user,'63000000-0000-4000-8000-000000000001'); PERFORM pg_temp.flush(); END $$;
GRANT EXECUTE ON FUNCTION pg_temp.flush(),pg_temp.assign(uuid,uuid[]),pg_temp.remove(uuid),pg_temp.edit_role(jsonb,text),pg_temp.add_owner(uuid,text),pg_temp.transfer(uuid) TO authenticated;
SELECT is((SELECT count(*) FROM public.notifications),0::bigint,'fixture membership and initial role assignment do not notify');
SELECT ok(NOT has_table_privilege('authenticated','private.account_notification_state','SELECT'),'browser cannot read private permission state');
SELECT ok(NOT has_function_privilege('service_role','private.flush_account_notifications()','EXECUTE'),'backend cannot forge account notifications');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='private.account_notification_state'::regclass),'private comparison state has RLS');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"account-session-1"}',true);
SELECT pg_temp.assign('63000000-0000-4000-8000-000000000002',ARRAY['63000000-0000-4000-8000-000000000030']::uuid[]);
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000002'),1::bigint,'assignment changes effective permission exactly once');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"account-session-1"}',true);
SELECT pg_temp.assign('63000000-0000-4000-8000-000000000002',ARRAY['63000000-0000-4000-8000-000000000030']::uuid[]);
SELECT pg_temp.assign('63000000-0000-4000-8000-000000000002',ARRAY['63000000-0000-4000-8000-000000000031']::uuid[]);
SELECT pg_temp.assign('63000000-0000-4000-8000-000000000002',ARRAY['63000000-0000-4000-8000-000000000030','63000000-0000-4000-8000-000000000031']::uuid[]);
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000002'),1::bigint,'retry equivalent role and redundant overlapping role do not notify');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"account-session-1"}',true);
SELECT pg_temp.edit_role('{"records":{"view":"assigned"}}','Renamed role');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000002'),1::bigint,'name only change does not notify');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"account-session-1"}',true);
SELECT pg_temp.edit_role('{"records":{"view":"all"}}');
SELECT pg_temp.edit_role('{"records":{"view":"all"}}');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000002'),2::bigint,'shared role permission edit notifies affected member once');
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000003'),1::bigint,'other affected member is notified');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000004","role":"authenticated","session_id":"account-session-4"}',true);
SELECT throws_ok($q$ SELECT pg_temp.assign('63000000-0000-4000-8000-000000000002',ARRAY['63000000-0000-4000-8000-000000000032']::uuid[]) $q$,'P0001','owner_required','non owner cannot grant dangerous permissions');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000005","role":"authenticated","session_id":"account-session-5"}',true);
SELECT throws_ok($q$ SELECT pg_temp.assign('63000000-0000-4000-8000-000000000002',ARRAY['63000000-0000-4000-8000-000000000030']::uuid[]) $q$,'P0001','permission_denied','foreign owner cannot change roles');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"expired"}',true);
SELECT throws_ok($q$ SELECT pg_temp.assign('63000000-0000-4000-8000-000000000002',ARRAY['63000000-0000-4000-8000-000000000030']::uuid[]) $q$,'P0001','authentication_required','inactive session denied');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications),3::bigint,'failed mutations leave no notifications');
INSERT INTO public.reauth_grants(token_hash,user_id,auth_session_id,purpose,expires_at) VALUES(encode(extensions.digest('account-owner-add','sha256'),'hex'),'63000000-0000-4000-8000-000000000001','account-session-1','owner_add',now()+interval '10 minutes');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"account-session-1"}',true);
SELECT pg_temp.add_owner('63000000-0000-4000-8000-000000000002','account-owner-add');
SELECT throws_ok($q$ SELECT pg_temp.add_owner('63000000-0000-4000-8000-000000000003','account-owner-add') $q$,'P0001','owner_add_requires_reauthentication','owner addition proof replay denied');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000002'),3::bigint,'owner promotion notifies target once');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000004","role":"authenticated","session_id":"account-session-4"}',true);
SELECT throws_ok($q$ SELECT pg_temp.remove('63000000-0000-4000-8000-000000000002') $q$,'42501','owner_required','account manager cannot remove owner');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"account-session-1"}',true);
SELECT pg_temp.transfer('63000000-0000-4000-8000-000000000003');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000003'),2::bigint,'owner transfer notifies promoted target');
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000001'),0::bigint,'explicit self demotion does not notify');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000003","role":"authenticated","session_id":"account-session-3"}',true);
SELECT pg_temp.assign('63000000-0000-4000-8000-000000000004',ARRAY['63000000-0000-4000-8000-000000000032','63000000-0000-4000-8000-000000000030']::uuid[]);
SELECT public.mutate_organization_role_authorized('63000000-0000-4000-8000-000000000010','63000000-0000-4000-8000-000000000030','delete',NULL,NULL,NULL,false);
SELECT pg_temp.flush();
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000002'),3::bigint,'owner effective permissions ignore business role deletion');
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.permissions_changed' AND user_id='63000000-0000-4000-8000-000000000004'),2::bigint,'role deletion notifies members whose effective permission decreased');
CREATE FUNCTION public.account_fixture_fail_permissions() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF NEW.event_type='account.permissions_changed' THEN RAISE EXCEPTION 'fixture_notification_failed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER account_fixture_fail_permissions BEFORE INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.account_fixture_fail_permissions();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000003","role":"authenticated","session_id":"account-session-3"}',true);
SELECT throws_ok($q$ SELECT pg_temp.assign('63000000-0000-4000-8000-000000000004',ARRAY[]::uuid[]) $q$,'P0001','fixture_notification_failed','notification failure rolls back permission mutation');
RESET ROLE;
SELECT ok(EXISTS(SELECT 1 FROM public.organization_member_roles WHERE user_id='63000000-0000-4000-8000-000000000004' AND role_id='63000000-0000-4000-8000-000000000032'),'failed notification preserves business role assignment');
DROP TRIGGER account_fixture_fail_permissions ON public.notifications;
CREATE FUNCTION public.account_fixture_fail_notice() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF NEW.event_type='account.removed_from_organization' THEN RAISE EXCEPTION 'fixture_notification_failed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER account_fixture_fail_notice BEFORE INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.account_fixture_fail_notice();
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000003","role":"authenticated","session_id":"account-session-3"}',true);
SELECT throws_ok($q$ SELECT pg_temp.remove('63000000-0000-4000-8000-000000000002') $q$,'P0001','fixture_notification_failed','notification failure rolls back removal');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.removed_from_organization'),0::bigint,'failed removal leaves no removal notice');
SELECT ok(EXISTS(SELECT 1 FROM public.organization_members WHERE organization_id='63000000-0000-4000-8000-000000000010' AND user_id='63000000-0000-4000-8000-000000000002'),'notification failure preserves membership');
DROP TRIGGER account_fixture_fail_notice ON public.notifications;
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000003","role":"authenticated","session_id":"account-session-3"}',true);
SELECT pg_temp.remove('63000000-0000-4000-8000-000000000002');
SELECT throws_ok($q$ SELECT pg_temp.remove('63000000-0000-4000-8000-000000000002') $q$,'P0001','member_not_found','removal replay rejected');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE event_type='account.removed_from_organization' AND user_id='63000000-0000-4000-8000-000000000002'),1::bigint,'removed account notified exactly once');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"account-session-2"}',true);
SELECT is((SELECT count(*) FROM public.notifications),4::bigint,'former member can read own notifications without membership');
SELECT is((SELECT count(*) FROM public.organization_members WHERE organization_id='63000000-0000-4000-8000-000000000010'),0::bigint,'notification does not grant access to organization membership');
UPDATE public.notifications SET is_read=true WHERE event_type='account.removed_from_organization';
SELECT ok((SELECT is_read FROM public.notifications WHERE event_type='account.removed_from_organization'),'former member can mark removal notice read');
RESET ROLE;
SELECT ok(NOT EXISTS(SELECT 1 FROM public.notifications WHERE event_type LIKE 'account.%' AND (category<>'action_required' OR link_url IS NOT NULL OR resource_id<>user_id OR content LIKE '%example.invalid%' OR content LIKE '%records%')),'account notices are fixed actionable text without internal destinations or permission JSON');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000004","role":"authenticated","session_id":"account-session-4"}',true);
SELECT pg_temp.assign('63000000-0000-4000-8000-000000000004',ARRAY['63000000-0000-4000-8000-000000000031']::uuid[]);
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications WHERE user_id='63000000-0000-4000-8000-000000000004'),2::bigint,'authorized explicit self role change does not notify');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"63000000-0000-4000-8000-000000000003","role":"authenticated","session_id":"account-session-3"}',true);
SELECT public.create_invitation_authorized('63000000-0000-4000-8000-000000000010','account-invite','invited@example.invalid','Synthetic invited');
SELECT throws_ok($q$ SELECT public.account_update_role('63000000-0000-4000-8000-000000000010',(SELECT id FROM public.invitations WHERE code='account-invite'),'invited','member') $q$,'23514',NULL,'existing invitation role constraint rejects member value without notification');
SELECT public.account_remove('63000000-0000-4000-8000-000000000010',(SELECT id FROM public.invitations WHERE code='account-invite'),'invited');
SELECT pg_temp.flush();
RESET ROLE;
SELECT is((SELECT count(*) FROM public.notifications),8::bigint,'invitation creation edit and deletion do not notify');
SELECT * FROM finish();
ROLLBACK;
